body:
ES Version: 0.90.0.RC2

Steps to reproduce:

ok case, without source exclusion:

``` bash
curl -XDELETE 'http://localhost:9200/geo_test'
curl -XPUT 'http://localhost:9200/geo_test'
curl -XPUT 'http://localhost:9200/geo_test/item/_mapping' -d '{
    "item" : {
        "properties" : {
            "location" : {
                "type" : "object",
                "properties": {
                     "point": {"type": "geo_point"},
                     "area": {"type": "geo_shape"}
                }
            }
        }
    }
}'
curl -XPUT 'http://localhost:9200/geo_test/item/1' -d '{
    "location": {"point": [45.0, 45.0]}
}'
curl -XPUT 'http://localhost:9200/geo_test/item/2' -d '{
    "location": {
        "area": {
            "type" : "envelope",
            "coordinates" : [[44.0, 46.0], [45.0, 45.0]]
        }
    }
}'
curl -XPOST 'http://localhost:9200/geo_test/item/_search?pretty' -d '{
    "query": {"match_all": {}}
}'
```

returns the coordinates for geo_point and geo_shape items:

``` JSON
{
    "took": 1,
    "timed_out": false,
    "_shards": {
        "total": 1,
        "successful": 1,
        "failed": 0
    },
    "hits": {
        "total": 2,
        "max_score": 1.0,
        "hits": [{
            "_index": "geo_test",
            "_type": "item",
            "_id": "1",
            "_score": 1.0,
            "_source": {
                "location": {
                    "point": [45.0, 45.0]
                }
            }
        }, {
            "_index": "geo_test",
            "_type": "item",
            "_id": "2",
            "_score": 1.0,
            "_source": {
                "location": {
                    "area": {
                        "type": "envelope",
                        "coordinates": [
                            [45.0, 45.0],
                            [44.0, 46.0]
                        ]
                    }
                }
            }
        }]
    }
}
```

however the same scenario but with a source exclusion mapping of an arbitrary field does not return the geo_shape coordinates any longer:

``` bash
curl -XDELETE 'http://localhost:9200/geo_test'
curl -XPUT 'http://localhost:9200/geo_test'
curl -XPUT 'http://localhost:9200/geo_test/item/_mapping' -d '{
    "item": {
        "_source": {
            "excludes": ["body"]
        },
        "properties" : {
            "location" : {
                "type" : "object",
                "properties": {
                     "point": {"type": "geo_point"},
                     "area": {"type": "geo_shape"}
                }
            }
        }
    }
}'
curl -XPUT 'http://localhost:9200/geo_test/item/1' -d '{
    "location": {"point": [45.0, 45.0]}
}'
curl -XPUT 'http://localhost:9200/geo_test/item/2' -d '{
    "location": {
        "area": {
            "type" : "envelope",
            "coordinates" : [[44.0, 46.0], [45.0, 45.0]]
        }
    }
}'
curl -XPOST 'http://localhost:9200/geo_test/item/_search?pretty' -d '{
    "query": {"match_all": {}}
}'
```

returns only the geo_point coordinates but not the geo_shape coordinates:

``` JSON
{
    "took": 1,
    "timed_out": false,
    "_shards": {
        "total": 1,
        "successful": 1,
        "failed": 0
    },
    "hits": {
        "total": 2,
        "max_score": 1.0,
        "hits": [{
            "_index": "geo_test",
            "_type": "item",
            "_id": "1",
            "_score": 1.0,
            "_source": {
                "location": {
                    "point": [45.0, 45.0]
                }
            }
        }, {
            "_index": "geo_test",
            "_type": "item",
            "_id": "2",
            "_score": 1.0,
            "_source": {
                "location": {
                    "area": {
                        "type": "envelope",
                        "coordinates": []
                    }
                }
            }
        }]
    }
}
```
